PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>

SELECT ?m ?name (?deptTeam / ?fullteam * 100 AS ?pct)
WHERE {

  ?m pv:name ?name .

  { # full team
    SELECT ?m (COUNT(*) AS ?fullteam) WHERE {
      ?e pv:hasManager ?m .
    } GROUP BY ?m
  }

  { # team in same dept
    SELECT ?m (COUNT(*) AS ?deptTeam) WHERE {
      ?m pv:memberOf ?dept .
      ?e pv:hasManager ?m .
      ?e pv:memberOf ?dept .
    } GROUP BY ?m
  }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX pv: <http://ld.company.org/prod-vocab/>

SELECT ?bom ?avgUnitCost
WHERE {
  {
    SELECT ?bom (ROUND(AVG(?spst / ?sq) * 100) / 100 AS ?avgUnitCost)
    WHERE {
      {
        SELECT ?bom (SUM(?partSubTotal) AS ?spst) (SUM(xsd:int(?quant)) AS ?sq)
        WHERE {
          ?bom a pv:BillOfMaterial ;
               pv:hasBomPart ?part .
          ?part pv:quantity ?quant .
          ?part pv:hasPart/pv:price/pv:amount ?amount .
          ?part pv:hasPart/pv:price/pv:currency "EUR" .
          BIND(xsd:int(?quant) * ?amount AS ?partSubTotal)
        }
        GROUP BY ?bom
      }
    }
    GROUP BY ?bom
  }

  {
    SELECT (MAX(?avg) AS ?maxAvg)
    WHERE {
      {
        SELECT ?bom (ROUND(AVG(?spst / ?sq) * 100) / 100 AS ?avg)
        WHERE {
          {
            SELECT ?bom (SUM(?partSubTotal) AS ?spst) (SUM(xsd:int(?quant)) AS ?sq)
            WHERE {
              ?bom a pv:BillOfMaterial ;
                   pv:hasBomPart ?part .
              ?part pv:quantity ?quant .
              ?part pv:hasPart/pv:price/pv:amount ?amount .
              ?part pv:hasPart/pv:price/pv:currency "EUR" .
              BIND(xsd:int(?quant) * ?amount AS ?partSubTotal)
            }
            GROUP BY ?bom
          }
        }
        GROUP BY ?bom
      }
    }
  }

  FILTER (?avgUnitCost = ?maxAvg)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>

SELECT ?id ?name ?width
WHERE {
  { # get min-max range
    SELECT (MIN(?width) AS ?minW) (MAX(?width) AS ?maxW)
    WHERE {
      ?hw a pv:Hardware ;
        pv:width_mm ?width .
    }
  }

  # get 90. percentile
  BIND(?minW + (0.9 * (?maxW - ?minW)) AS ?pct90)

  ?hw a pv:Hardware ;
    pv:id ?id ;
    pv:name ?name ;
    pv:width_mm ?width .

  FILTER(?width >= ?pct90)
}
ORDER BY DESC(?width)

PREFIX pv: <http://ld.company.org/prod-vocab/>

SELECT DISTINCT ?result
WHERE {
  ?hardware pv:hasCategory <http://ld.company.org/prod-instances/prod-cat-Inductor> .
  ?hardware pv:reliabilityIndex ?reliabilityIndex .
  ?hardware pv:hasSupplier ?result .

  {
    SELECT (MAX(?ri) AS ?maxRI)
    WHERE {
      ?h pv:hasCategory <http://ld.company.org/prod-instances/prod-cat-Inductor> .
      ?h pv:reliabilityIndex ?ri .
    }
  }

  FILTER(?reliabilityIndex = ?maxRI)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>

SELECT ?supplier ?avgReliability
WHERE {
  {
    SELECT ?supplier (AVG(?ri) AS ?avgReliability)
    WHERE {
      ?hardware pv:hasSupplier ?supplier ;
                pv:reliabilityIndex ?ri .
    }
    GROUP BY ?supplier
  }

  {
    SELECT (MIN(?topVal) AS ?threshold)
    WHERE {
      SELECT (AVG(?ri) AS ?topVal)
      WHERE {
        ?h pv:hasSupplier ?s ;
           pv:reliabilityIndex ?ri .
      }
      GROUP BY ?s
      ORDER BY DESC(?topVal)
      LIMIT 5
    }
  }

  FILTER(?avgReliability >= ?threshold)
}
ORDER BY DESC(?avgReliability) ?supplier

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (COUNT(DISTINCT ?supplier) AS ?result)
WHERE {
  <http://ld.company.org/prod-instances/hw-K367-1320550> pv:compatibleProduct ?alternative .
  ?alternative pv:hasSupplier ?supplier .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>

SELECT ?result ?count
WHERE {
  {
    SELECT ?result (COUNT(?product) AS ?count)
    WHERE {
      ?result pv:responsibleFor ?product .
    }
    GROUP BY ?result
  }
  {
    SELECT (MAX(?c_inner) AS ?maxCount)
    WHERE {
      SELECT ?r_inner (COUNT(?p_inner) AS ?c_inner)
      WHERE {
        ?r_inner pv:responsibleFor ?p_inner .
      }
      GROUP BY ?r_inner
    }
  }
  FILTER (?count = ?maxCount)
}
